on conflict (prompt_id, provider_id) do update
  set compatibility = excluded.compatibility, status = excluded.status,
      fallback_behavior = excluded.fallback_behavior, support_notes = excluded.support_notes;

insert into public.prompt_versions (variant_id, version_label, payload, status, is_current, published_at)
select v.id, 'v3.0', l.payload, 'published'::public.version_status, true, now()
from lot_v3 l
join public.prompts p on p.external_ref = l.external_ref
join public.prompt_variants v on v.prompt_id = p.id
where not exists (
  select 1 from public.prompt_versions pv where pv.variant_id = v.id and pv.payload = l.payload);

-- Questions contextuelles : remplacees en bloc, leur ordre fait leur sens.
